def is_symmetric(pattern):
    """Check if pattern is symmetric horizontally and vertically"""
    h, w = len(pattern), len(pattern[0])

    # Vertical symmetry (flip rows)
    for r in range(h // 2):
        if pattern[r] != pattern[h - 1 - r]:
            return False

    # Horizontal symmetry (flip columns per row)
    for r in range(h):
        for c in range(w // 2):
            if pattern[r][c] != pattern[r][w - 1 - c]:
                return False

    return True

