    components = []

    for r in range(separator_row):
        for c in range(w):
            if grid[r][c] != 0 and grid[r][c] != 5 and not visited[r][c]:
                color = grid[r][c]
                cells = []
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    cells.append((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < separator_row and 0 <= nc < w:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                components.append((color, cells))

